import React, { useEffect, useMemo, useState } from 'react';
import {
  Activity, AlertCircle, Archive, Bell, CheckCircle2, ChevronRight, ClipboardList,
  Database, FileText, Image as ImageIcon, LayoutDashboard, LogOut, Mail, Menu,
  MessageSquare, MoreHorizontal, Plus, RefreshCw, Search, Settings, Shield,
  SlidersHorizontal, Trash2, Upload, UserCog, Users, X
} from 'lucide-react';
import { supabase } from '../../lib/supabase';
import { restoreAdminSession, signOut } from '../../lib/supabaseAuth';

type Section = 'overview'|'applications'|'messages'|'content'|'services'|'media'|'users'|'roles'|'emails'|'audit'|'settings';
const navy='#0d0a64', red='#e7020b';

const nav = [
 {key:'overview',label:'Overview',icon:LayoutDashboard},
 {key:'applications',label:'Applications',icon:ClipboardList},
 {key:'messages',label:'Contact Inbox',icon:MessageSquare},
 {key:'content',label:'Website CMS',icon:FileText},
 {key:'services',label:'Services',icon:SlidersHorizontal},
 {key:'media',label:'Media Library',icon:ImageIcon},
 {key:'users',label:'Users & Staff',icon:Users},
 {key:'roles',label:'Roles & Permissions',icon:Shield},
 {key:'emails',label:'Email Log',icon:Mail},
 {key:'audit',label:'Audit Trail',icon:Activity},
 {key:'settings',label:'Site Settings',icon:Settings},
] as const;

const statusStyles:any={NEW:'bg-amber-50 text-amber-700 border-amber-200',REVIEWING:'bg-blue-50 text-blue-700 border-blue-200',CONTACTED:'bg-indigo-50 text-indigo-700 border-indigo-200',PROCESSING:'bg-purple-50 text-purple-700 border-purple-200',COMPLETED:'bg-emerald-50 text-emerald-700 border-emerald-200',DECLINED:'bg-red-50 text-red-700 border-red-200',CLOSED:'bg-slate-50 text-slate-600 border-slate-200',READ:'bg-blue-50 text-blue-700 border-blue-200',SPAM:'bg-red-50 text-red-700 border-red-200'};

function Badge({value}:{value:string}){return <span className={`inline-flex items-center px-2 py-1 rounded-full border text-[10px] font-bold ${statusStyles[value]||'bg-slate-50 text-slate-600 border-slate-200'}`}>{value.replaceAll('_',' ')}</span>}
function Card({children,className='' }:{children:React.ReactNode,className?:string}){return <div className={`bg-white border border-slate-200 rounded-2xl shadow-[0_6px_24px_rgba(13,10,100,.05)] ${className}`}>{children}</div>}
function Button({children,onClick,variant='primary',disabled=false}:{children:React.ReactNode,onClick?:()=>void,variant?:'primary'|'soft'|'ghost'|'danger',disabled?:boolean}){const c={primary:'bg-[#e7020b] text-white',soft:'bg-slate-100 text-slate-700',ghost:'bg-white text-slate-700 border border-slate-200',danger:'bg-red-600 text-white'} as any;return <button disabled={disabled} onClick={onClick} className={`px-3.5 py-2 rounded-xl text-xs font-bold transition disabled:opacity-50 ${c[variant]}`}>{children}</button>}

export const AdminDashboardPage:React.FC=()=>{
 const [section,setSection]=useState<Section>('overview');
 const [session,setSession]=useState<any>(null);
 const [collapsed,setCollapsed]=useState(false);
 const [loading,setLoading]=useState(true);
 const [error,setError]=useState('');
 const [toast,setToast]=useState('');
 useEffect(()=>{restoreAdminSession().then(x=>{if(!x) window.location.replace('/admin/login'); else setSession(x)}).catch(()=>window.location.replace('/admin/login')).finally(()=>setLoading(false))},[]);
 useEffect(()=>{if(toast){const t=setTimeout(()=>setToast(''),3500);return()=>clearTimeout(t)}},[toast]);
 if(loading) return <div className="min-h-screen bg-slate-50 grid place-items-center"><div className="text-sm font-bold text-slate-500">Loading management workspace…</div></div>;
 if(!session) return null;
 const displayRole=session.roles?.map((r:any)=>r.role?.name||r.role?.key).join(', ')||session.profile?.role||'Staff';
 return <div className="min-h-screen bg-[#f6f8fc] text-slate-800">
  <aside className={`fixed inset-y-0 left-0 z-40 bg-[#0b0a3d] text-white transition-all ${collapsed?'w-[76px]':'w-[260px]'}`}>
   <div className="h-16 px-4 flex items-center justify-between border-b border-white/10"><div className={`${collapsed?'hidden':''} font-extrabold tracking-tight`}>EMUNAHH<span className="text-[#e7020b]">.</span><span className="block text-[9px] tracking-[.28em] text-white/45">MANAGEMENT CMS</span></div><button onClick={()=>setCollapsed(!collapsed)} className="p-2 rounded-lg hover:bg-white/10"><Menu className="w-4 h-4"/></button></div>
   <div className="p-3 space-y-1">{nav.map(n=>{const I=n.icon;return <button key={n.key} onClick={()=>setSection(n.key)} title={n.label} className={`w-full flex items-center gap-3 px-3 py-2.5 rounded-xl text-xs font-semibold ${section===n.key?'bg-white text-[#0b0a3d]':'text-white/65 hover:bg-white/10 hover:text-white'}`}><I className="w-4 h-4 shrink-0"/>{!collapsed&&<span>{n.label}</span>}</button>})}</div>
   <div className="absolute bottom-0 left-0 right-0 p-3 border-t border-white/10"><button onClick={async()=>{await signOut();window.location.replace('/admin/login')}} className="w-full flex items-center gap-3 px-3 py-2.5 text-xs font-semibold text-white/60 hover:text-white"><LogOut className="w-4 h-4"/>{!collapsed&&'Sign out'}</button></div>
  </aside>
  <main className={`${collapsed?'ml-[76px]':'ml-[260px]'} min-h-screen transition-all`}>
   <header className="sticky top-0 z-30 h-16 bg-white/90 backdrop-blur border-b border-slate-200 px-5 lg:px-8 flex items-center justify-between">
    <div><div className="text-[10px] uppercase tracking-[.18em] text-slate-400 font-bold">Control Centre</div><h1 className="text-lg font-extrabold text-[#0d0a64]">{nav.find(x=>x.key===section)?.label}</h1></div>
    <div className="flex items-center gap-3"><div className="hidden sm:block text-right"><div className="text-xs font-bold text-slate-700">{session.profile?.full_name||session.user.email}</div><div className="text-[10px] text-slate-400 uppercase">{displayRole}</div></div><div className="w-9 h-9 rounded-xl bg-[#e3fff2] text-[#0d0a64] grid place-items-center font-bold text-xs">{(session.profile?.full_name||session.user.email||'A').slice(0,1).toUpperCase()}</div></div>
   </header>
   <div className="p-4 lg:p-8 max-w-[1500px] mx-auto">
    {error&&<div className="mb-4 p-3 rounded-xl bg-red-50 text-red-700 text-xs border border-red-200 flex gap-2"><AlertCircle className="w-4 h-4"/>{error}</div>}
    {toast&&<div className="fixed right-5 bottom-5 z-50 bg-[#0b0a3d] text-white px-4 py-3 rounded-xl shadow-2xl text-xs font-semibold">{toast}</div>}
    <SectionRouter section={section} setSection={setSection} notify={setToast} setError={setError}/>
   </div>
  </main>
 </div>
}

function SectionRouter({section,setSection,notify,setError}:{section:Section,setSection:(s:Section)=>void,notify:(s:string)=>void,setError:(s:string)=>void}){
 switch(section){
  case 'overview': return <Overview setSection={setSection}/>;
  case 'applications': return <Applications notify={notify}/>;
  case 'messages': return <Messages notify={notify}/>;
  case 'content': return <ContentCMS notify={notify}/>;
  case 'services': return <Services notify={notify}/>;
  case 'media': return <Media notify={notify}/>;
  case 'users': return <UsersAdmin notify={notify}/>;
  case 'roles': return <Roles notify={notify}/>;
  case 'emails': return <Emails/>;
  case 'audit': return <Audit/>;
  case 'settings': return <SettingsPage notify={notify}/>;
 }
}

function Overview({setSection}:{setSection:(s:Section)=>void}){
 const [stats,setStats]=useState<any>({}); const [recent,setRecent]=useState<any[]>([]);
 const load=async()=>{const [{count:apps},{count:msgs},{count:services},{count:users},{count:newApps}]=await Promise.all([
  supabase.from('applications').select('*',{count:'exact',head:true}),supabase.from('contact_messages').select('*',{count:'exact',head:true}),
  supabase.from('services').select('*',{count:'exact',head:true}).eq('is_published',true),supabase.from('profiles').select('*',{count:'exact',head:true}),
  supabase.from('applications').select('*',{count:'exact',head:true}).eq('status','NEW')]);setStats({apps,msgs,services,users,newApps});
  const {data}=await supabase.from('applications').select('reference,full_name,application_type,status,created_at').order('created_at',{ascending:false}).limit(8);setRecent(data||[]);
 };
 useEffect(()=>{load()},[]);
 const cards=[['Applications',stats.apps,'applications',ClipboardList],['New Applications',stats.newApps,'applications',Bell],['Contact Messages',stats.msgs,'messages',MessageSquare],['Published Services',stats.services,'services',SlidersHorizontal],['Staff Accounts',stats.users,'users',Users]];
 return <div className="space-y-6">
  <div className="flex items-end justify-between"><div><p className="text-sm text-slate-500">Live operational snapshot</p><h2 className="text-2xl font-extrabold text-[#0d0a64]">Good to see you.</h2></div><Button variant="soft" onClick={load}><RefreshCw className="w-3.5 h-3.5 inline mr-2"/>Refresh</Button></div>
  <div className="grid grid-cols-2 xl:grid-cols-5 gap-4">{cards.map(([label,val,target,I]:any)=><button key={label} onClick={()=>setSection(target)} className="text-left bg-white border border-slate-200 rounded-2xl p-5 hover:border-[#e7020b]/40"><I className="w-5 h-5 text-[#e7020b]"/><div className="text-2xl font-extrabold text-[#0d0a64] mt-4">{val??'—'}</div><div className="text-xs text-slate-500 mt-1">{label}</div></button>)}</div>
  <div className="grid lg:grid-cols-3 gap-5">
   <Card className="lg:col-span-2 overflow-hidden"><div className="px-5 py-4 border-b border-slate-100 flex justify-between"><div><h3 className="font-extrabold text-[#0d0a64]">Recent applications</h3><p className="text-[11px] text-slate-400">Latest customer intake records</p></div><button onClick={()=>setSection('applications')} className="text-xs font-bold text-[#e7020b]">View all</button></div><div className="divide-y divide-slate-100">{recent.map(r=><div key={r.reference} className="px-5 py-4 flex items-center justify-between gap-4"><div><div className="text-xs font-bold">{r.full_name}</div><div className="text-[10px] text-slate-400">{r.reference} · {r.application_type.replaceAll('_',' ')}</div></div><div className="text-right"><Badge value={r.status}/><div className="text-[10px] text-slate-400 mt-1">{new Date(r.created_at).toLocaleString('en-GB')}</div></div></div>)}</div></Card>
   <Card className="p-5"><h3 className="font-extrabold text-[#0d0a64]">Admin shortcuts</h3><div className="mt-4 space-y-2">{[['Add staff','users',Users],['Edit website','content',FileText],['Upload media','media',Upload],['Review messages','messages',MessageSquare]].map(([x,t,I]:any)=><button onClick={()=>setSection(t)} key={x} className="w-full flex items-center gap-3 p-3 rounded-xl bg-slate-50 hover:bg-slate-100 text-xs font-bold"><I className="w-4 h-4 text-[#e7020b]"/>{x}<ChevronRight className="w-3.5 h-3.5 ml-auto text-slate-400"/></button>)}</div></Card>
  </div>
 </div>
}

function Applications({notify}:{notify:(s:string)=>void}){
 const [rows,setRows]=useState<any[]>([]),[q,setQ]=useState(''),[status,setStatus]=useState('ALL'),[selected,setSelected]=useState<any>(null),[loading,setLoading]=useState(true);
 const load=async()=>{setLoading(true);let query=supabase.from('applications').select('*, services(title)').order('created_at',{ascending:false}).limit(200);if(status!=='ALL')query=query.eq('status',status);const {data}=await query;setRows(data||[]);setLoading(false)};useEffect(()=>{load()},[status]);
 const filtered=useMemo(()=>rows.filter(r=>`${r.full_name} ${r.reference} ${r.phone} ${r.email||''}`.toLowerCase().includes(q.toLowerCase())),[rows,q]);
 const update=async(id:string,next:string)=>{const {error}=await supabase.from('applications').update({status:next}).eq('id',id);if(error) notify(error.message);else {notify('Application status updated');load();if(selected?.id===id)setSelected({...selected,status:next})}};
 return <div className="space-y-4">
  <Toolbar search={q} setSearch={setQ} refresh={load} placeholder="Search applicant, reference, phone…"/><div className="flex gap-2 overflow-auto pb-1">{['ALL','NEW','REVIEWING','CONTACTED','PROCESSING','COMPLETED','DECLINED','CLOSED'].map(x=><button key={x} onClick={()=>setStatus(x)} className={`px-3 py-1.5 rounded-lg text-[10px] font-bold whitespace-nowrap ${status===x?'bg-[#0d0a64] text-white':'bg-white border border-slate-200 text-slate-500'}`}>{x}</button>)}</div>
  <Card className="overflow-hidden"><div className="overflow-x-auto"><table className="w-full text-left"><thead className="bg-slate-50 border-b border-slate-200"><tr>{['Reference','Applicant','Type','Amount','Status','Submitted',''].map(x=><th key={x} className="px-4 py-3 text-[10px] uppercase tracking-wider text-slate-400 font-bold">{x}</th>)}</tr></thead><tbody className="divide-y divide-slate-100">{loading?<tr><td colSpan={7} className="p-8 text-center text-xs text-slate-400">Loading…</td></tr>:filtered.map(r=><tr key={r.id} className="hover:bg-slate-50"><td className="px-4 py-3 font-mono text-[10px] font-bold text-[#0d0a64]">{r.reference}</td><td className="px-4 py-3"><div className="text-xs font-bold">{r.full_name}</div><div className="text-[10px] text-slate-400">{r.phone}</div></td><td className="px-4 py-3 text-[10px] capitalize">{r.application_type.replaceAll('_',' ')}</td><td className="px-4 py-3 text-xs">{r.amount||'—'}</td><td className="px-4 py-3"><Badge value={r.status}/></td><td className="px-4 py-3 text-[10px] text-slate-400">{new Date(r.created_at).toLocaleDateString('en-GB')}</td><td className="px-4 py-3 text-right"><button onClick={()=>setSelected(r)} className="p-2 hover:bg-slate-100 rounded-lg"><MoreHorizontal className="w-4 h-4"/></button></td></tr>)}</tbody></table></div></Card>
  {selected&&<ApplicationDrawer row={selected} close={()=>setSelected(null)} update={update} notify={notify}/>}
 </div>
}

function ApplicationDrawer({row,close,update,notify}:{row:any,close:()=>void,update:(id:string,s:string)=>void,notify:(s:string)=>void}){
 const [notes,setNotes]=useState<any[]>([]),[note,setNote]=useState(''),[email,setEmail]=useState(''),[subject,setSubject]=useState(''),[body,setBody]=useState('');
 useEffect(()=>{supabase.from('application_notes').select('*').eq('application_id',row.id).order('created_at',{ascending:false}).then(({data})=>setNotes(data||[]));setEmail(row.email||'')},[row.id]);
 const addNote=async()=>{if(!note.trim())return;const {data:{user}}=await supabase.auth.getUser();const {error}=await supabase.from('application_notes').insert({application_id:row.id,author_id:user?.id,note:note.trim()});if(error)notify(error.message);else{setNotes([{note,created_at:new Date().toISOString()},...notes]);setNote('');notify('Internal note added')}}; 
 const send=async()=>{if(!email||!subject||!body)return;const {error}=await supabase.functions.invoke('send-email',{body:{to:email,subject,html:`<div style="font-family:Arial;line-height:1.6">${body.replace(/\n/g,'<br/>')}</div>`,application_id:row.id}});if(error)notify(error.message);else{notify('Email request submitted');setSubject('');setBody('')}}; 
 return <div className="fixed inset-0 z-50 bg-slate-950/40 backdrop-blur-sm flex justify-end"><div className="w-full max-w-xl bg-white h-full overflow-auto shadow-2xl"><div className="sticky top-0 bg-white border-b p-5 flex justify-between"><div><div className="font-mono text-[10px] text-[#e7020b] font-bold">{row.reference}</div><h2 className="font-extrabold text-[#0d0a64]">{row.full_name}</h2></div><button onClick={close}><X/></button></div><div className="p-5 space-y-6">
  <div className="grid grid-cols-2 gap-3">{[['Phone',row.phone],['Email',row.email||'—'],['Type',row.application_type.replaceAll('_',' ')],['Amount',row.amount||'—'],['Institution/Business',row.institution_or_business||'—']].map(([a,b])=><div key={a} className="bg-slate-50 rounded-xl p-3"><div className="text-[10px] text-slate-400">{a}</div><div className="text-xs font-bold mt-1 break-words">{b}</div></div>)}</div>
  <div><div className="text-[10px] uppercase tracking-wider text-slate-400 font-bold mb-2">Workflow status</div><div className="flex flex-wrap gap-2">{['NEW','REVIEWING','CONTACTED','PROCESSING','COMPLETED','DECLINED','CLOSED'].map(s=><button key={s} onClick={()=>update(row.id,s)} className={`px-2.5 py-1.5 rounded-lg text-[10px] font-bold border ${row.status===s?'bg-[#0d0a64] text-white':'border-slate-200 text-slate-500'}`}>{s}</button>)}</div></div>
  <div><div className="text-[10px] uppercase tracking-wider text-slate-400 font-bold mb-2">Applicant details</div><pre className="whitespace-pre-wrap bg-slate-950 text-slate-200 rounded-xl p-4 text-[11px] overflow-auto">{JSON.stringify(row.details||{},null,2)}</pre></div>
  <div><div className="flex justify-between items-center mb-2"><div className="text-[10px] uppercase tracking-wider text-slate-400 font-bold">Internal notes</div><Button onClick={addNote} variant="soft">Add note</Button></div><textarea value={note} onChange={e=>setNote(e.target.value)} rows={2} className="w-full border rounded-xl p-3 text-xs mb-3" placeholder="Private operational note…"/><div className="space-y-2">{notes.map((n,i)=><div key={i} className="bg-amber-50 border border-amber-100 rounded-xl p-3 text-xs"><div>{n.note}</div><div className="text-[9px] text-slate-400 mt-1">{n.created_at&&new Date(n.created_at).toLocaleString('en-GB')}</div></div>)}</div></div>
  <div className="border-t pt-5"><div className="text-[10px] uppercase tracking-wider text-slate-400 font-bold mb-2">Send applicant email</div><input value={email} onChange={e=>setEmail(e.target.value)} className="w-full border rounded-xl p-2.5 text-xs mb-2" placeholder="Recipient"/><input value={subject} onChange={e=>setSubject(e.target.value)} className="w-full border rounded-xl p-2.5 text-xs mb-2" placeholder="Subject"/><textarea value={body} onChange={e=>setBody(e.target.value)} rows={5} className="w-full border rounded-xl p-3 text-xs" placeholder="Message…"/><div className="flex justify-end mt-2"><Button onClick={send}>Send email</Button></div></div>
 </div></div></div>
}

function Messages({notify}:{notify:(s:string)=>void}){
 const [rows,setRows]=useState<any[]>([]),[selected,setSelected]=useState<any>(null),[q,setQ]=useState('');
 const load=async()=>{const {data}=await supabase.from('contact_messages').select('*').order('created_at',{ascending:false}).limit(300);setRows(data||[])};useEffect(()=>{load()},[]);
 const filtered=rows.filter(r=>`${r.reference} ${r.name} ${r.email||''} ${r.phone}`.toLowerCase().includes(q.toLowerCase()));
 const update=async(id:string,status:string)=>{const {error}=await supabase.from('contact_messages').update({status}).eq('id',id);if(error)notify(error.message);else{notify('Inbox updated');load();setSelected(null)}};
 return <div className="space-y-4"><Toolbar search={q} setSearch={setQ} refresh={load} placeholder="Search contact inbox…"/><Card className="overflow-hidden divide-y divide-slate-100">{filtered.map(r=><button key={r.id} onClick={()=>setSelected(r)} className="w-full text-left p-4 hover:bg-slate-50 flex items-center gap-4"><div className="w-10 h-10 rounded-xl bg-[#e3fff2] text-[#0d0a64] grid place-items-center font-bold">{r.name.slice(0,1)}</div><div className="min-w-0 flex-1"><div className="flex justify-between"><div className="text-xs font-bold">{r.name}</div><Badge value={r.status}/></div><div className="text-[10px] text-slate-400">{r.reference} · {r.service||'General'} · {r.phone}</div><div className="text-xs text-slate-600 truncate mt-1">{r.message}</div></div><ChevronRight className="w-4 h-4 text-slate-300"/></button>)}{!filtered.length&&<Empty/>}</Card>
 {selected&&<div className="fixed inset-0 z-50 bg-slate-950/40 flex items-center justify-center p-4"><Card className="max-w-xl w-full p-6"><div className="flex justify-between"><div><div className="font-mono text-[10px] text-[#e7020b]">{selected.reference}</div><h2 className="text-xl font-extrabold text-[#0d0a64]">{selected.name}</h2></div><button onClick={()=>setSelected(null)}><X/></button></div><div className="mt-5 space-y-3 text-xs"><div><b>Phone:</b> {selected.phone}</div><div><b>Email:</b> {selected.email||'—'}</div><div><b>Service:</b> {selected.service||'—'}</div><div className="bg-slate-50 rounded-xl p-4 whitespace-pre-wrap">{selected.message}</div></div><div className="mt-5 flex flex-wrap gap-2">{['READ','CONTACTED','CLOSED','SPAM'].map(s=><Button key={s} variant={s==='SPAM'?'danger':'soft'} onClick={()=>update(selected.id,s)}>{s}</Button>)}</div></Card></div>}</div>
}

function ContentCMS({notify}:{notify:(s:string)=>void}){
 const [pages,setPages]=useState<any[]>([]),[selected,setSelected]=useState<any>(null),[sections,setSections]=useState<any[]>([]),[draft,setDraft]=useState<any>(null),[saving,setSaving]=useState(false),[newPage,setNewPage]=useState(false);
 const load=async()=>{const {data,error}=await supabase.from('cms_pages').select('*').order('title');if(error){notify(error.message);return}setPages(data||[]);if(selected){const fresh=(data||[]).find((p:any)=>p.id===selected.id);if(fresh)setSelected(fresh)}};
 const loadSections=async(page:any)=>{setSelected(page);setDraft({...page});const {data,error}=await supabase.from('cms_sections').select('*').eq('page_id',page.id).order('display_order');if(error)notify(error.message);else setSections(data||[])};
 useEffect(()=>{load()},[]);
 const savePage=async()=>{if(!draft?.title||!draft?.slug)return notify('Page title and slug are required.');setSaving(true);const user=(await supabase.auth.getUser()).data.user;const {error}=await supabase.from('cms_pages').update({title:draft.title,slug:draft.slug,status:draft.status,menu_label:draft.menu_label,show_in_header:draft.show_in_header,show_in_footer:draft.show_in_footer,seo_title:draft.seo_title||null,seo_description:draft.seo_description||null,og_image_url:draft.og_image_url||null,canonical_url:draft.canonical_url||null,robots:draft.robots||'index,follow',updated_by:user?.id}).eq('id',draft.id);setSaving(false);if(error)notify(error.message);else{notify('Page settings saved');load()}};
 const addPage=async(page:any)=>{const {data,error}=await supabase.from('cms_pages').insert({slug:page.slug,title:page.title,menu_label:page.title,template:'standard',status:'draft',seo_title:page.title,seo_description:'',show_in_header:false,show_in_footer:true}).select().single();if(error){notify(error.message);return}notify('Page created');setNewPage(false);await load();if(data)loadSections(data)};
 const saveSection=async(section:any)=>{const user=(await supabase.auth.getUser()).data.user;await supabase.from('cms_revisions').insert({page_id:section.page_id,section_id:section.id,snapshot:section,created_by:user?.id});const {error}=await supabase.from('cms_sections').update({label:section.label,content:section.content,is_enabled:section.is_enabled,display_order:Number(section.display_order||0),background:section.background||'white',anchor_id:section.anchor_id||null,section_type:section.section_type,updated_by:user?.id}).eq('id',section.id);if(error)notify(error.message);else{notify(`${section.label} saved`);loadSections(selected)}};
 const addSection=async()=>{if(!selected)return;const max=Math.max(0,...sections.map(s=>Number(s.display_order||0)));const {data,error}=await supabase.from('cms_sections').insert({page_id:selected.id,section_key:`section-${Date.now()}`,label:'New Section',section_type:'features',content:{eyebrow:'SECTION',heading:'New section',items:[]},display_order:max+1,is_enabled:true,background:'white'}).select().single();if(error)notify(error.message);else{notify('Section added');setSections([...sections,data])}};
 const deleteSection=async(id:string)=>{if(!confirm('Delete this section? This cannot be undone.'))return;const {error}=await supabase.from('cms_sections').delete().eq('id',id);if(error)notify(error.message);else{notify('Section deleted');setSections(sections.filter(x=>x.id!==id))}};
 return <div className="space-y-5">
  <div className="flex flex-col lg:flex-row lg:items-center justify-between gap-3"><div><h2 className="text-xl font-extrabold text-[#0d0a64]">Visual Website CMS</h2><p className="text-xs text-slate-500 mt-1">Edit pages, sections, images, buttons and SEO without touching React code.</p></div><div className="flex gap-2"><Button variant="soft" onClick={load}><RefreshCw className="w-3.5 h-3.5 inline mr-1"/>Refresh</Button><Button onClick={()=>setNewPage(true)}><Plus className="w-3.5 h-3.5 inline mr-1"/>New page</Button></div></div>
  <div className="grid xl:grid-cols-[270px_1fr] gap-5">
   <Card className="p-3 h-fit"><div className="px-2 py-2 text-[10px] uppercase tracking-wider text-slate-400 font-bold">Pages</div>{pages.map(p=><button key={p.id} onClick={()=>loadSections(p)} className={`w-full text-left px-3 py-3 rounded-xl mb-1 ${selected?.id===p.id?'bg-[#0d0a64] text-white':'hover:bg-slate-50'}`}><div className="flex items-center justify-between gap-2"><span className="text-xs font-bold truncate">{p.menu_label||p.title}</span><span className={`text-[9px] ${selected?.id===p.id?'text-white/60':'text-slate-400'}`}>{p.status}</span></div><div className={`text-[10px] mt-1 ${selected?.id===p.id?'text-white/60':'text-slate-400'}`}>/{p.slug}</div></button>)}{!pages.length&&<div className="p-4 text-xs text-slate-400">No CMS pages found. Run migration 004.</div>}</Card>
   <div className="space-y-5">{selected?<>
    <Card className="p-5"><div className="flex flex-col md:flex-row md:items-start md:justify-between gap-4"><div><div className="text-[10px] uppercase tracking-wider text-[#e7020b] font-bold">Page settings</div><h2 className="text-xl font-extrabold text-[#0d0a64]">{selected.title}</h2></div><Button onClick={savePage}>{saving?'Saving…':'Save page settings'}</Button></div><div className="grid md:grid-cols-2 gap-4 mt-5"><Field label="Page title" value={draft?.title||''} onChange={v=>setDraft({...draft,title:v})}/><Field label="URL slug" value={draft?.slug||''} onChange={v=>setDraft({...draft,slug:v.replace(/\s+/g,'-').toLowerCase()})}/><Field label="Menu label" value={draft?.menu_label||''} onChange={v=>setDraft({...draft,menu_label:v})}/><Field label="Status" value={draft?.status||'draft'} onChange={v=>setDraft({...draft,status:v})} select options={['draft','published','archived']}/><Field label="SEO title" value={draft?.seo_title||''} onChange={v=>setDraft({...draft,seo_title:v})}/><Field label="Canonical URL" value={draft?.canonical_url||''} onChange={v=>setDraft({...draft,canonical_url:v})}/><div className="md:col-span-2"><Field label="SEO description" value={draft?.seo_description||''} onChange={v=>setDraft({...draft,seo_description:v})} textarea/></div><Field label="Robots" value={draft?.robots||'index,follow'} onChange={v=>setDraft({...draft,robots:v})}/><Field label="Open Graph image URL" value={draft?.og_image_url||''} onChange={v=>setDraft({...draft,og_image_url:v})}/></div><div className="flex gap-5 mt-4 text-xs font-semibold"><label><input type="checkbox" checked={!!draft?.show_in_header} onChange={e=>setDraft({...draft,show_in_header:e.target.checked})} className="mr-2"/>Header navigation</label><label><input type="checkbox" checked={!!draft?.show_in_footer} onChange={e=>setDraft({...draft,show_in_footer:e.target.checked})} className="mr-2"/>Footer navigation</label></div></Card>
    <Card className="p-5"><div className="flex items-center justify-between mb-5"><div><h3 className="font-extrabold text-[#0d0a64]">Page sections</h3><p className="text-[10px] text-slate-400">Every visible section is editable with normal fields—no JSON.</p></div><Button variant="soft" onClick={addSection}><Plus className="w-3.5 h-3.5 inline mr-1"/>Add section</Button></div><div className="space-y-4">{sections.map(s=><VisualSectionEditor key={s.id} section={s} onSave={saveSection} onDelete={()=>deleteSection(s.id)}/>)}</div></Card>
   </>:<Card className="p-12 text-center"><FileText className="mx-auto text-slate-300 w-8 h-8"/><p className="text-sm font-bold mt-3 text-[#0d0a64]">Select a page to edit</p><p className="text-xs text-slate-400 mt-1">The public website reads published CMS sections directly from Supabase.</p></Card>}</div>
  </div>{newPage&&<Modal title="Create website page" close={()=>setNewPage(false)}><NewPageForm onCancel={()=>setNewPage(false)} onCreate={addPage}/></Modal>}</div>
}

function NewPageForm({onCancel,onCreate}:{onCancel:()=>void;onCreate:(x:any)=>void}){const [title,setTitle]=useState('');const [slug,setSlug]=useState('');return <div className="space-y-4"><Field label="Page title" value={title} onChange={v=>{setTitle(v);if(!slug)setSlug(v.toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/(^-|-$)/g,''))}}/><Field label="URL slug" value={slug} onChange={setSlug}/><div className="flex justify-end gap-2"><Button variant="soft" onClick={onCancel}>Cancel</Button><Button disabled={!title||!slug} onClick={()=>onCreate({title,slug})}>Create page</Button></div></div>}

function VisualSectionEditor({section,onSave,onDelete}:{section:any;onSave:(x:any)=>void;onDelete:()=>void}){const [open,setOpen]=useState(false);const [draft,setDraft]=useState<any>({...section,content:structuredClone(section.content||{})});const set=(key:string,value:any)=>setDraft((d:any)=>({...d,content:{...d.content,[key]:value}}));const type=draft.section_type;return <div className="border border-slate-200 rounded-2xl overflow-hidden"><button onClick={()=>setOpen(!open)} className="w-full px-5 py-4 flex items-center justify-between text-left hover:bg-slate-50"><div><div className="text-sm font-extrabold text-[#0d0a64]">{draft.label}</div><div className="text-[10px] text-slate-400 mt-1">{draft.section_key} · {type}</div></div><ChevronRight className={`w-4 h-4 transition ${open?'rotate-90':''}`}/></button>{open&&<div className="p-5 border-t space-y-5"><div className="grid md:grid-cols-3 gap-3"><Field label="Section label" value={draft.label||''} onChange={v=>setDraft({...draft,label:v})}/><Field label="Section type" value={type} onChange={v=>setDraft({...draft,section_type:v})} select options={['hero','trust','split','cards','features','steps','faq','cta','contact','legal']}/><Field label="Background" value={draft.background||'white'} onChange={v=>setDraft({...draft,background:v})} select options={['white','soft','mint','navy']}/></div><label className="text-xs font-semibold flex items-center gap-2"><input type="checkbox" checked={!!draft.is_enabled} onChange={e=>setDraft({...draft,is_enabled:e.target.checked})}/> Section visible on website</label><SectionFields type={type} content={draft.content} set={set}/><div className="flex justify-between pt-2"><Button variant="danger" onClick={onDelete}><Trash2 className="w-3.5 h-3.5 inline mr-1"/>Delete</Button><Button onClick={()=>onSave(draft)}>Save section</Button></div></div>}</div>}

function SectionFields({type,content,set}:{type:string;content:any;set:(k:string,v:any)=>void}){const uploadImage=async()=>{const input=document.createElement('input');input.type='file';input.accept='image/*';input.onchange=async()=>{const file=input.files?.[0];if(!file)return;const cloud=import.meta.env.VITE_CLOUDINARY_CLOUD_NAME,preset=import.meta.env.VITE_CLOUDINARY_UPLOAD_PRESET;if(!cloud||!preset){alert('Configure VITE_CLOUDINARY_CLOUD_NAME and VITE_CLOUDINARY_UPLOAD_PRESET first.');return}const fd=new FormData();fd.append('file',file);fd.append('upload_preset',preset);const res=await fetch(`https://api.cloudinary.com/v1_1/${cloud}/image/upload`,{method:'POST',body:fd});if(!res.ok){alert('Cloudinary upload failed.');return}const data=await res.json();set('imageUrl',data.secure_url)};input.click()};
 const listEditor=(key:string,fields:string[],label:string)=>{const items=Array.isArray(content[key])?content[key]:[];return <div><div className="flex justify-between items-center mb-2"><span className="text-[10px] uppercase tracking-wider font-bold text-slate-400">{label}</span><button type="button" onClick={()=>set(key,[...items,Object.fromEntries(fields.map(f=>[f,'']))])} className="text-[10px] font-bold text-[#e7020b]">+ Add</button></div><div className="space-y-3">{items.map((item:any,i:number)=><div key={i} className="p-4 bg-slate-50 rounded-xl border border-slate-200"><div className="grid md:grid-cols-2 gap-3">{fields.map(f=><Field key={f} label={f.replaceAll('_',' ')} value={(typeof item==='string'?(f==='value'?item:''):item[f])||''} onChange={v=>{const next=[...items];next[i]={...(typeof item==='string'?{value:item}:item),[f]:v};set(key,next)}} textarea={f==='description'||f==='answer'||f==='body'}/>)}</div><button type="button" onClick={()=>set(key,items.filter((_:any,j:number)=>j!==i))} className="mt-3 text-[10px] font-bold text-red-500">Remove</button></div>)}</div></div>};
 if(type==='hero')return <div className="grid md:grid-cols-2 gap-4"><Field label="Eyebrow" value={content.eyebrow||''} onChange={v=>set('eyebrow',v)}/><Field label="Heading" value={content.heading||''} onChange={v=>set('heading',v)} textarea/><Field label="Description" value={content.description||''} onChange={v=>set('description',v)} textarea/><Field label="Primary CTA" value={content.primaryCta||''} onChange={v=>set('primaryCta',v)}/><Field label="Primary link" value={content.primaryHref||'/apply'} onChange={v=>set('primaryHref',v)}/><Field label="Secondary CTA" value={content.secondaryCta||''} onChange={v=>set('secondaryCta',v)}/><Field label="Secondary link" value={content.secondaryHref||'/contact'} onChange={v=>set('secondaryHref',v)}/><div className="md:col-span-2"><div className="flex gap-2"><Field label="Image URL" value={content.imageUrl||''} onChange={v=>set('imageUrl',v)}/><div className="pt-6"><Button variant="soft" onClick={uploadImage}>Upload image</Button></div></div>{content.imageUrl&&<img src={content.imageUrl} className="mt-3 w-48 h-28 rounded-xl object-cover border"/>}</div></div>;
 if(type==='split')return <div className="space-y-4"><div className="grid md:grid-cols-2 gap-4"><Field label="Eyebrow" value={content.eyebrow||''} onChange={v=>set('eyebrow',v)}/><Field label="Heading" value={content.heading||''} onChange={v=>set('heading',v)} textarea/><Field label="Description" value={content.description||''} onChange={v=>set('description',v)} textarea/><Field label="Image URL" value={content.imageUrl||''} onChange={v=>set('imageUrl',v)}/></div>{listEditor('points',['value'],'Bullet points')}</div>;
 if(type==='cards'||type==='features')return <div className="space-y-4"><div className="grid md:grid-cols-2 gap-4"><Field label="Eyebrow" value={content.eyebrow||''} onChange={v=>set('eyebrow',v)}/><Field label="Heading" value={content.heading||''} onChange={v=>set('heading',v)} textarea/><Field label="Description" value={content.description||''} onChange={v=>set('description',v)} textarea/></div>{listEditor('items',type==='cards'?['title','description','cta','href']:['title','description'],'Items')}</div>;
 if(type==='steps')return <div className="space-y-4"><div className="grid md:grid-cols-2 gap-4"><Field label="Eyebrow" value={content.eyebrow||''} onChange={v=>set('eyebrow',v)}/><Field label="Heading" value={content.heading||''} onChange={v=>set('heading',v)}/></div>{listEditor('steps',['number','title','description'],'Steps')}</div>;
 if(type==='faq')return listEditor('items',['question','answer'],'Questions & answers');
 if(type==='legal')return listEditor('sections',['title','body'],'Legal sections');
 if(type==='contact')return <div className="grid md:grid-cols-2 gap-4"><Field label="Heading" value={content.heading||''} onChange={v=>set('heading',v)}/><Field label="Phone" value={content.phone||''} onChange={v=>set('phone',v)}/><Field label="Email" value={content.email||''} onChange={v=>set('email',v)}/><Field label="Hours" value={content.hours||''} onChange={v=>set('hours',v)}/><div className="md:col-span-2"><Field label="Address / description" value={content.description||''} onChange={v=>set('description',v)} textarea/></div></div>;
 if(type==='cta')return <div className="grid md:grid-cols-2 gap-4"><Field label="Heading" value={content.heading||''} onChange={v=>set('heading',v)} textarea/><Field label="Description" value={content.description||''} onChange={v=>set('description',v)} textarea/><Field label="Button text" value={content.buttonText||''} onChange={v=>set('buttonText',v)}/><Field label="Button link" value={content.href||'/contact'} onChange={v=>set('href',v)}/></div>;
 if(type==='trust')return <div>{listEditor('items',['value'],'Trust points')}</div>;
 return <Field label="Section text" value={content.description||''} onChange={v=>set('description',v)} textarea/>;
}

function Services({notify}:{notify:(s:string)=>void}){const [rows,setRows]=useState<any[]>([]),[edit,setEdit]=useState<any>(null);const load=async()=>{const {data}=await supabase.from('services').select('*').order('display_order');setRows(data||[])};useEffect(()=>{load()},[]);const save=async()=>{if(!edit.title)return;const payload={slug:edit.slug,title:edit.title,category:edit.category,tagline:edit.tagline,description:edit.description,bullets:edit.bullets||[],image_url:edit.image_url||null,is_published:edit.is_published,display_order:Number(edit.display_order||0)};const {error}=edit.id?await supabase.from('services').update(payload).eq('id',edit.id):await supabase.from('services').insert(payload);if(error)notify(error.message);else{notify('Service saved');setEdit(null);load()}};const remove=async(id:string)=>{if(!confirm('Delete this service?'))return;const {error}=await supabase.from('services').delete().eq('id',id);if(error)notify(error.message);else load()};return <div className="space-y-4"><div className="flex justify-end"><Button onClick={()=>setEdit({title:'',slug:'',category:'supporting',tagline:'',description:'',bullets:[],image_url:'',is_published:true,display_order:rows.length+1})}><Plus className="w-3.5 h-3.5 inline mr-1"/>Add service</Button></div><Card className="divide-y divide-slate-100">{rows.map(r=><div key={r.id} className="p-4 flex items-center gap-4"><div className="w-14 h-14 rounded-xl bg-slate-100 overflow-hidden">{r.image_url&&<img src={r.image_url} className="w-full h-full object-cover" />}</div><div className="flex-1"><div className="text-xs font-bold text-[#0d0a64]">{r.title}</div><div className="text-[10px] text-slate-400">{r.slug} · order {r.display_order}</div></div><Badge value={r.is_published?'PUBLISHED':'DRAFT'}/><Button variant="soft" onClick={()=>setEdit(r)}>Edit</Button><button onClick={()=>remove(r.id)} className="p-2 text-red-500"><Trash2 className="w-4 h-4"/></button></div>)}</Card>{edit&&<Modal title={edit.id?'Edit service':'New service'} close={()=>setEdit(null)}><div className="grid md:grid-cols-2 gap-3"><Field label="Title" value={edit.title} onChange={v=>setEdit({...edit,title:v})}/><Field label="Slug" value={edit.slug} onChange={v=>setEdit({...edit,slug:v})}/><Field label="Tagline" value={edit.tagline||''} onChange={v=>setEdit({...edit,tagline:v})}/><Field label="Image URL (Cloudinary)" value={edit.image_url||''} onChange={v=>setEdit({...edit,image_url:v})}/><div className="md:col-span-2"><Field label="Description" value={edit.description||''} onChange={v=>setEdit({...edit,description:v})} textarea/></div><div className="md:col-span-2"><Field label="Bullets (one per line)" value={(edit.bullets||[]).join('\n')} onChange={v=>setEdit({...edit,bullets:v.split('\n').filter(Boolean)})} textarea/></div><label className="text-xs flex items-center gap-2"><input type="checkbox" checked={edit.is_published} onChange={e=>setEdit({...edit,is_published:e.target.checked})}/> Published</label></div><div className="flex justify-end mt-5"><Button onClick={save}>Save service</Button></div></Modal>}</div>}

function Media({notify}:{notify:(s:string)=>void}){const [rows,setRows]=useState<any[]>([]),[uploading,setUploading]=useState(false);const load=async()=>{const {data}=await supabase.from('media').select('*').order('created_at',{ascending:false});setRows(data||[])};useEffect(()=>{load()},[]);const upload=async(file:File)=>{setUploading(true);try{const cloud=import.meta.env.VITE_CLOUDINARY_CLOUD_NAME,preset=import.meta.env.VITE_CLOUDINARY_UPLOAD_PRESET;if(!cloud||!preset)throw new Error('Cloudinary upload variables are not configured.');const fd=new FormData();fd.append('file',file);fd.append('upload_preset',preset);const res=await fetch(`https://api.cloudinary.com/v1_1/${cloud}/auto/upload`,{method:'POST',body:fd});if(!res.ok)throw new Error('Cloudinary upload failed');const data=await res.json();const user=(await supabase.auth.getUser()).data.user;const {error}=await supabase.from('media').insert({filename:file.name,storage_path:data.public_id,public_url:data.secure_url,title:file.name,alt_text:'',category:'general',mime_type:file.type,file_size:file.size,uploaded_by:user?.id});if(error)throw error;notify('Media uploaded');load()}catch(e){notify(e instanceof Error?e.message:'Upload failed')}finally{setUploading(false)}};return <div className="space-y-4"><Card className="p-5 border-dashed"><label className="flex flex-col items-center justify-center py-8 cursor-pointer"><Upload className="w-7 h-7 text-[#e7020b]"/><div className="font-bold text-sm mt-2">{uploading?'Uploading…':'Upload to Cloudinary'}</div><div className="text-[10px] text-slate-400 mt-1">WebP/AVIF/JPG/PNG · optimize before publishing</div><input type="file" accept="image/*" className="hidden" onChange={e=>e.target.files?.[0]&&upload(e.target.files[0])}/></label></Card><div className="grid grid-cols-2 md:grid-cols-4 xl:grid-cols-6 gap-4">{rows.map(r=><div key={r.id} className="bg-white border rounded-xl overflow-hidden"><div className="aspect-square bg-slate-100"><img src={r.public_url} className="w-full h-full object-cover" loading="lazy"/></div><div className="p-2"><div className="text-[10px] font-bold truncate">{r.filename}</div><div className="text-[9px] text-slate-400">{Math.round((r.file_size||0)/1024)} KB</div></div></div>)}</div></div>}

function UsersAdmin({notify}:{notify:(s:string)=>void}){const [rows,setRows]=useState<any[]>([]),[roles,setRoles]=useState<any[]>([]),[show,setShow]=useState(false);const load=async()=>{const [{data:u},{data:r}]=await Promise.all([supabase.from('profiles').select('*, departments(name)').order('created_at',{ascending:false}),supabase.from('roles').select('*').order('name')]);setRows(u||[]);setRoles(r||[])};useEffect(()=>{load()},[]);const changeRole=async(id:string,key:string)=>{const role=roles.find(r=>r.key===key);if(!role)return;const {error}=await supabase.from('user_roles').upsert({user_id:id,role_id:role.id});if(error)notify(error.message);else{await supabase.from('profiles').update({role:key}).eq('id',id);notify('Role updated');load()}};return <div className="space-y-4"><div className="flex justify-end"><Button onClick={()=>setShow(true)}><Plus className="w-3.5 h-3.5 inline mr-1"/>Create user</Button></div><Card className="overflow-hidden"><table className="w-full"><thead className="bg-slate-50"><tr>{['User','Role','Department','Status',''].map(x=><th key={x} className="text-left px-4 py-3 text-[10px] uppercase text-slate-400">{x}</th>)}</tr></thead><tbody className="divide-y">{rows.map(r=><tr key={r.id}><td className="px-4 py-3"><div className="text-xs font-bold">{r.full_name||'Unnamed user'}</div><div className="text-[10px] text-slate-400">{r.id}</div></td><td className="px-4 py-3"><select value={r.role} onChange={e=>changeRole(r.id,e.target.value)} className="border rounded-lg px-2 py-1 text-[10px]">{roles.map(x=><option key={x.key}>{x.key}</option>)}</select></td><td className="px-4 py-3 text-xs">{r.departments?.name||'—'}</td><td className="px-4 py-3"><Badge value={r.status==='active'?'ACTIVE':'DISABLED'}/></td><td className="px-4 py-3 text-right"><button onClick={async()=>{await supabase.from('profiles').update({status:r.status==='active'?'disabled':'active'}).eq('id',r.id);load()}} className="text-[10px] font-bold text-[#e7020b]">{r.status==='active'?'Disable':'Enable'}</button></td></tr>)}</tbody></table></Card>{show&&<CreateUserModal close={()=>setShow(false)} notify={notify} roles={roles} after={load}/>}</div>}

function CreateUserModal({close,notify,roles,after}:{close:()=>void,notify:(s:string)=>void,roles:any[],after:()=>void}){const [email,setEmail]=useState(''),[name,setName]=useState(''),[role,setRole]=useState('staff'),[department,setDepartment]=useState(''),[saving,setSaving]=useState(false);const [deps,setDeps]=useState<any[]>([]);useEffect(()=>{supabase.from('departments').select('*').eq('is_active',true).order('name').then(({data})=>setDeps(data||[]))},[]);const save=async()=>{setSaving(true);const {data,error}=await supabase.functions.invoke('admin-user-management',{body:{action:'invite',email,name,role,department_id:department||null}});setSaving(false);if(error||data?.error){notify(error?.message||data.error);return}notify('User invitation sent');after();close()};return <Modal title="Create management user" close={close}><div className="space-y-3"><Field label="Full name" value={name} onChange={setName}/><Field label="Email" value={email} onChange={setEmail}/><Field label="Role" value={role} onChange={setRole} select options={roles.map(r=>r.key)}/><Field label="Department" value={department} onChange={setDepartment} select options={['',...deps.map(d=>d.id)]} optionLabels={['—',...deps.map(d=>d.name)]}/><div className="p-3 bg-amber-50 rounded-xl text-[10px] text-amber-700">The user receives a secure Supabase invitation email. No password is stored by this admin form.</div><div className="flex justify-end"><Button disabled={saving} onClick={save}>{saving?'Creating…':'Create & invite'}</Button></div></div></Modal>}

function Roles({notify}:{notify:(s:string)=>void}){const [roles,setRoles]=useState<any[]>([]),[permissions,setPermissions]=useState<any[]>([]);const load=async()=>{const [{data:r},{data:p}]=await Promise.all([supabase.from('roles').select('*').order('name'),supabase.from('permissions').select('*').order('module,key')]);setRoles(r||[]);setPermissions(p||[])};useEffect(()=>{load()},[]);const toggle=async(role:any,p:any)=>{const {data:rp}=await supabase.from('role_permissions').select('*').eq('role_id',role.id).eq('permission_id',p.id).maybeSingle();if(rp)await supabase.from('role_permissions').delete().eq('role_id',role.id).eq('permission_id',p.id);else await supabase.from('role_permissions').insert({role_id:role.id,permission_id:p.id});notify('Permission matrix updated')};return <div className="space-y-4"><Card className="overflow-auto"><table className="w-full min-w-[850px]"><thead className="bg-slate-50"><tr><th className="text-left px-4 py-3 text-[10px] uppercase text-slate-400">Permission</th>{roles.map(r=><th key={r.id} className="px-3 py-3 text-[10px] uppercase text-slate-400">{r.key}</th>)}</tr></thead><tbody className="divide-y">{permissions.map(p=><PermissionRow key={p.id} p={p} roles={roles} toggle={toggle}/>)}</tbody></table></Card><p className="text-[10px] text-slate-400">Super Admin is always unrestricted. Changes are enforced by Supabase Row Level Security, not only by hiding UI.</p></div>}
function PermissionRow({p,roles,toggle}:{p:any,roles:any[],toggle:(r:any,p:any)=>void}){const [ids,setIds]=useState<string[]>([]);useEffect(()=>{supabase.from('role_permissions').select('role_id').eq('permission_id',p.id).then(({data})=>setIds((data||[]).map(x=>x.role_id)))},[p.id]);return <tr><td className="px-4 py-3"><div className="text-xs font-bold">{p.label}</div><div className="text-[9px] text-slate-400">{p.key}</div></td>{roles.map(r=><td key={r.id} className="text-center"><input type="checkbox" checked={ids.includes(r.id)} disabled={r.key==='super_admin'} onChange={async()=>{await toggle(r,p);setIds(ids.includes(r.id)?ids.filter(x=>x!==r.id):[...ids,r.id])}}/></td>)}</tr>}

function Emails(){const [rows,setRows]=useState<any[]>([]);useEffect(()=>{supabase.from('email_logs').select('*').order('created_at',{ascending:false}).limit(300).then(({data})=>setRows(data||[]))},[]);return <Card className="overflow-hidden"><table className="w-full"><thead className="bg-slate-50"><tr>{['Recipient','Subject','Status','Date'].map(x=><th key={x} className="text-left px-4 py-3 text-[10px] uppercase text-slate-400">{x}</th>)}</tr></thead><tbody className="divide-y">{rows.map(r=><tr key={r.id}><td className="px-4 py-3 text-xs">{r.recipient}</td><td className="px-4 py-3 text-xs">{r.subject}</td><td className="px-4 py-3"><Badge value={r.status}/></td><td className="px-4 py-3 text-[10px] text-slate-400">{new Date(r.created_at).toLocaleString('en-GB')}</td></tr>)}{!rows.length&&<tr><td colSpan={4}><Empty/></td></tr>}</tbody></table></Card>}
function Audit(){const [rows,setRows]=useState<any[]>([]);useEffect(()=>{supabase.from('audit_logs').select('*').order('created_at',{ascending:false}).limit(300).then(({data})=>setRows(data||[]))},[]);return <Card className="divide-y">{rows.map(r=><div key={r.id} className="p-4 flex gap-3"><Activity className="w-4 h-4 text-[#e7020b]"/><div><div className="text-xs font-bold">{r.action}</div><div className="text-[10px] text-slate-400">{r.entity_type||'system'} · {r.entity_id||'—'} · {new Date(r.created_at).toLocaleString('en-GB')}</div></div></div>)}{!rows.length&&<Empty/>}</Card>}
function SettingsPage({notify}:{notify:(s:string)=>void}){const [s,setS]=useState<any>({});useEffect(()=>{supabase.from('site_settings').select('*').eq('id',1).maybeSingle().then(({data})=>setS(data||{}))},[]);const save=async()=>{const {error}=await supabase.from('site_settings').update({company_name:s.company_name,company_email:s.company_email,notification_email:s.notification_email,phone:s.phone,secondary_phone:s.secondary_phone,whatsapp:s.whatsapp,office_address:s.office_address,email_sender_name:s.email_sender_name,reply_to_email:s.reply_to_email,website_url:s.website_url,logo_url:s.logo_url}).eq('id',1);notify(error?error.message:'Settings saved')};return <Card className="p-6"><div className="grid md:grid-cols-2 gap-4">{Object.keys(s).filter(k=>!['id','updated_at'].includes(k)).map(k=><Field key={k} label={k.replaceAll('_',' ')} value={s[k]||''} onChange={v=>setS({...s,[k]:v})}/>)}</div><div className="flex justify-end mt-5"><Button onClick={save}>Save settings</Button></div></Card>}

function Toolbar({search,setSearch,refresh,placeholder}:{search:string,setSearch:(s:string)=>void,refresh:()=>void,placeholder:string}){return <div className="flex gap-2"><div className="relative flex-1 max-w-xl"><Search className="absolute left-3 top-2.5 w-4 h-4 text-slate-400"/><input value={search} onChange={e=>setSearch(e.target.value)} placeholder={placeholder} className="w-full pl-9 pr-3 py-2.5 bg-white border border-slate-200 rounded-xl text-xs outline-none focus:border-[#e7020b]"/></div><Button variant="soft" onClick={refresh}><RefreshCw className="w-3.5 h-3.5 inline mr-1"/>Refresh</Button></div>}
function Field({label,value,onChange,textarea=false,select=false,options=[],optionLabels=[]}:{label:string,value:string,onChange:(v:string)=>void,textarea?:boolean,select?:boolean,options?:string[],optionLabels?:string[]}){return <label className="block"><span className="block text-[10px] uppercase tracking-wider text-slate-400 font-bold mb-1.5">{label}</span>{textarea?<textarea rows={4} value={value} onChange={e=>onChange(e.target.value)} className="w-full border border-slate-200 rounded-xl px-3 py-2.5 text-xs outline-none focus:border-[#e7020b]"/>:select?<select value={value} onChange={e=>onChange(e.target.value)} className="w-full border border-slate-200 rounded-xl px-3 py-2.5 text-xs">{options.map((o,i)=><option key={o} value={o}>{optionLabels[i]||o}</option>)}</select>:<input value={value} onChange={e=>onChange(e.target.value)} className="w-full border border-slate-200 rounded-xl px-3 py-2.5 text-xs outline-none focus:border-[#e7020b]"/>}</label>}
function Modal({title,close,children}:{title:string,close:()=>void,children:React.ReactNode}){return <div className="fixed inset-0 z-50 bg-slate-950/40 flex items-center justify-center p-4"><div className="bg-white rounded-2xl shadow-2xl w-full max-w-2xl max-h-[90vh] overflow-auto"><div className="sticky top-0 bg-white border-b p-5 flex justify-between"><h2 className="font-extrabold text-[#0d0a64]">{title}</h2><button onClick={close}><X className="w-5 h-5"/></button></div><div className="p-5">{children}</div></div></div>}
function Empty(){return <div className="p-10 text-center text-xs text-slate-400">No records found.</div>}
